-- TomoModForever 1.2.2 release notes.

TomoMod_RegisterLocale("enUS", {
    ["wn_122_tabs"] = "Fixed - Chat: whisper tabs now appear in the TomoMod tab row (they were missing and Blizzard's tab showed behind the panel). Tabs keep Blizzard's order, the open tab always follows the window you type in, and an incoming whisper no longer takes you off the tab you are reading.",
    ["wn_122_overflow"] = "New - Chat: a + button after the tabs opens a new tab: Guild, Group, Whispers, Trade (in cities), Loot, or any name you type. When the tabs no longer fit, the last ones go into a list at the end of the row, with an unread dot.",
})

TomoMod_RegisterLocale("frFR", {
